class Solution:
    def attention(self, Q: List[List[float]], K: List[List[float]], V: List[List[float]], causal: bool) -> List[List[float]]:
        d = len(Q[0])
        scale = 1.0 / math.sqrt(d)
        out_dim = len(V[0])
        outputs = []
        for i, q in enumerate(Q):
            scores = []
            for j, k in enumerate(K):
                if causal and j > i:
                    scores.append(float('-inf'))
                else:
                    scores.append(sum(a * b for a, b in zip(q, k)) * scale)
            m = max(scores)
            weights = [math.exp(s - m) for s in scores]
            total = sum(weights)
            weights = [w / total for w in weights]
            row = [0.0] * out_dim
            for w, v in zip(weights, V):
                if w:
                    for c in range(out_dim):
                        row[c] += w * v[c]
            outputs.append(row)
        return outputs

